using System.Collections.Generic;
using System.Collections.Immutable;
using System.Linq;
using System.Text;
using System.Threading;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace UnionGen;

[Generator]
public sealed class ValueUnionGenerator : IIncrementalGenerator
{
    private const string AttributeSource = """
        // <auto-generated/>
        namespace UnionGen
        {
            [global::System.AttributeUsage(global::System.AttributeTargets.Struct)]
            internal sealed class ValueUnionAttribute : global::System.Attribute;

            [global::System.AttributeUsage(global::System.AttributeTargets.Struct, AllowMultiple = true)]
            internal sealed class UnionCaseAttribute<T> : global::System.Attribute;
        }
        """;

    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(static ctx => ctx.AddSource("UnionGen-Attributes.g.cs", AttributeSource));

        var unions = context.SyntaxProvider.ForAttributeWithMetadataName(
            "UnionGen.ValueUnionAttribute",
            predicate: static (node, _) => node is StructDeclarationSyntax s
                && s.Modifiers.Any(SyntaxKind.PartialKeyword)
                && s.Parent is not TypeDeclarationSyntax
                && s.TypeParameterList is null,
            transform: static (ctx, ct) => ToModel((INamedTypeSymbol)ctx.TargetSymbol, ct));

        context.RegisterSourceOutput(unions, static (ctx, model) => ctx.AddSource(HintName(model), Emit(model)));
    }

    private static string HintName(UnionModel model) =>
        model.Namespace is null ? $"{model.Name}.g.cs" : $"{model.Namespace}.{model.Name}.g.cs";

    private static UnionModel ToModel(INamedTypeSymbol type, CancellationToken ct)
    {
        var cases = ImmutableArray.CreateBuilder<CaseModel>();
        var names = new HashSet<string>();

        foreach (var attribute in type.GetAttributes())
        {
            ct.ThrowIfCancellationRequested();
            if (attribute.AttributeClass is not { Name: "UnionCaseAttribute", TypeArguments.Length: 1 } ac
                || ac.ContainingNamespace.ToDisplayString() != "UnionGen")
            {
                continue;
            }

            var caseType = ac.TypeArguments[0];
            int tag = cases.Count + 1;
            var storage = caseType.IsReferenceType ? Storage.Reference
                : caseType.IsUnmanagedType ? Storage.Unmanaged
                : Storage.Managed;
            var typeName = caseType.WithNullableAnnotation(NullableAnnotation.NotAnnotated)
                .ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
            var parameterName = UniqueName("on" + caseType.Name, names);

            cases.Add(new CaseModel(tag, typeName, parameterName, storage));
        }

        var ns = type.ContainingNamespace.IsGlobalNamespace ? null : type.ContainingNamespace.ToDisplayString();
        return new UnionModel(ns, type.Name, type.IsReadOnly, new EquatableArray<CaseModel>(cases.ToImmutable()));
    }

    private static string UniqueName(string name, HashSet<string> taken)
    {
        var unique = name;
        for (int i = 2; !taken.Add(unique); i++) unique = name + i;
        return unique;
    }

    private static string Emit(UnionModel model)
    {
        var cases = model.Cases.ToList();
        var unmanaged = cases.Where(c => c.Storage == Storage.Unmanaged).ToList();
        var sb = new StringBuilder();

        sb.AppendLine("// <auto-generated/>");
        sb.AppendLine("#nullable enable");
        if (model.Namespace is not null) sb.AppendLine($"namespace {model.Namespace};");
        sb.AppendLine();
        sb.AppendLine("[global::System.Runtime.CompilerServices.Union]");
        sb.AppendLine($"{(model.IsReadOnly ? "readonly " : "")}partial struct {model.Name} : global::System.Runtime.CompilerServices.IUnion");
        sb.AppendLine("{");

        if (unmanaged.Count > 0)
        {
            sb.AppendLine("    [global::System.Runtime.InteropServices.StructLayout(global::System.Runtime.InteropServices.LayoutKind.Explicit)]");
            sb.AppendLine("    private struct __Unmanaged");
            sb.AppendLine("    {");
            foreach (var c in unmanaged)
                sb.AppendLine($"        [global::System.Runtime.InteropServices.FieldOffset(0)] public {c.TypeName} Case{c.Tag};");
            sb.AppendLine("    }");
            sb.AppendLine();
        }
        if (cases.Any(c => c.Storage == Storage.Reference)) sb.AppendLine("    private readonly object? _ref;");
        foreach (var c in cases.Where(c => c.Storage == Storage.Managed))
            sb.AppendLine($"    private readonly {c.TypeName} _case{c.Tag};");
        if (unmanaged.Count > 0) sb.AppendLine("    private readonly __Unmanaged _unmanaged;");
        sb.AppendLine("    private readonly byte _tag;");
        sb.AppendLine();

        foreach (var c in cases)
        {
            var assign = c.Storage switch
            {
                Storage.Reference => "_ref = value ?? throw new global::System.ArgumentNullException(nameof(value));",
                Storage.Unmanaged => $"_unmanaged.Case{c.Tag} = value;",
                _ => $"_case{c.Tag} = value;",
            };
            sb.AppendLine($"    public {model.Name}({c.TypeName} value) {{ _tag = {c.Tag}; {assign} }}");
        }
        sb.AppendLine();

        sb.AppendLine("    public object? Value => _tag switch");
        sb.AppendLine("    {");
        foreach (var c in cases) sb.AppendLine($"        {c.Tag} => (object){Read(c)},");
        sb.AppendLine("        _ => null,");
        sb.AppendLine("    };");
        sb.AppendLine();

        sb.AppendLine("    public bool HasValue => _tag != 0;");
        sb.AppendLine();
        foreach (var c in cases)
        {
            if (c.Storage == Storage.Reference)
            {
                sb.AppendLine($"    public bool TryGetValue([global::System.Diagnostics.CodeAnalysis.NotNullWhen(true)] out {c.TypeName}? value)");
                sb.AppendLine($"    {{ if (_tag == {c.Tag}) {{ value = {Read(c)}; return true; }} value = null; return false; }}");
            }
            else
            {
                sb.AppendLine($"    public bool TryGetValue(out {c.TypeName} value)");
                sb.AppendLine($"    {{ if (_tag == {c.Tag}) {{ value = {Read(c)}; return true; }} value = default; return false; }}");
            }
        }
        sb.AppendLine();

        var parameters = string.Join(", ", cases.Select(c => $"global::System.Func<{c.TypeName}, TResult> {c.ParameterName}"));
        sb.AppendLine($"    public TResult Match<TResult>({parameters}) => _tag switch");
        sb.AppendLine("    {");
        foreach (var c in cases) sb.AppendLine($"        {c.Tag} => {c.ParameterName}({Read(c)}),");
        sb.AppendLine($"        _ => throw new global::System.InvalidOperationException(\"default({model.Name}) holds no value.\"),");
        sb.AppendLine("    };");
        sb.AppendLine("}");

        return sb.ToString();

        static string Read(CaseModel c) => c.Storage switch
        {
            Storage.Reference => $"({c.TypeName})_ref!",
            Storage.Unmanaged => $"_unmanaged.Case{c.Tag}",
            _ => $"_case{c.Tag}",
        };
    }
}
